import Decimal from "decimal.js";
import { file, program, type File } from "omp-soroi/node";

/** Deterministic e2e surrogate, not a physical annealing model.
 * anneal("film", 2200) = { curve: 26, log: File containing "film=film\ntemperature=2200\ncurve=26\n" }.
 */
export default program(async (film: string, temperature: number): Promise<{ curve: number; log: File }> => {
  const curve = new Decimal(temperature).div(100).plus(film.length).toNumber();
  const log = `anneal-${crypto.randomUUID()}.txt`;
  await Bun.write(log, `film=${film}\ntemperature=${temperature}\ncurve=${curve}\n`);
  return { curve, log: file(log) };
});

