import { human } from "omp-soroi/node";

/** Ask for a numeric score. The result is exactly the human's numeric answer, not an AI fallback.
 * Requires Soroi SOR-13 (public human constructor and answer endpoint).
 */
export default human<[string], number>((question: string) => `Return one numeric score for: ${question}`);

import Decimal from "decimal.js";
import { program } from "omp-soroi/node";

/** Double a numeric atom. Example: calc(21) = 42. Uses the bundled pure-JS dependency. */
export default program(async (input: number): Promise<number> => new Decimal(input).times(2).toNumber());

import Decimal from "decimal.js";
import { program } from "omp-soroi/node";

/** Mean of the five positional scores (svm, rf, gp, knn, lr). Example: (6.5, 5, 4.5, 4.25, 5) = 5.05. */
export default program(async (svm: number, rf: number, gp: number, knn: number, lr: number): Promise<number> =>
  new Decimal(svm).plus(rf).plus(gp).plus(knn).plus(lr).div(5).toNumber(),
);

