async (label: string, duration_ms: number = 1000) => {
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(label)) throw new Error("label must contain 1–128 ASCII letters, digits, underscores or hyphens");
  if (!Number.isFinite(duration_ms) || duration_ms < 0) throw new Error("duration_ms must be finite and nonnegative");
  const markers = "/var/tmp/soroi-e2e/markers";
  await mkdir(markers, { recursive: true });
  await Bun.write(`${markers}/${label}`, `${JSON.stringify({ label, duration_ms })}\n`);
  console.log(`slow_step started: ${label} (${duration_ms} ms)`);
  await Bun.sleep(duration_ms);
  console.log(`slow_step finished: ${label}`);
  return { label, duration_ms };
}

