import { mkdir } from "node:fs/promises";
import { program } from "omp-soroi/node";

/** Write a startup marker before waiting. slow_step("probe", 25) returns { label: "probe", duration_ms: 25 }.
 * Marker: /var/tmp/soroi-e2e/markers/probe contains {"label":"probe","duration_ms":25} plus a newline.
 * Labels are single safe path components; duration is a finite nonnegative number of milliseconds.
 */
export default program<[label: string] | [label: string, duration_ms: number], { label: string; duration_ms: number }>(async (label: string, duration_ms: number = 1000) => {
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(label)) throw new Error("label must contain 1–128 ASCII letters, digits, underscores or hyphens");
  if (!Number.isFinite(duration_ms) || duration_ms < 0) throw new Error("duration_ms must be finite and nonnegative");
  const markers = "/var/tmp/soroi-e2e/markers";
  await mkdir(markers, { recursive: true });
  await Bun.write(`${markers}/${label}`, `${JSON.stringify({ label, duration_ms })}\n`);
  console.log(`slow_step started: ${label} (${duration_ms} ms)`);
  await Bun.sleep(duration_ms);
  console.log(`slow_step finished: ${label}`);
  return { label, duration_ms };
});

import { agent } from "omp-soroi/node";

/** End with plain text and deliberately omit the only capture handback channel. */
export default agent<[string], string>(
  (token: string) => `This is the no-handback negative workload. End this turn with exactly the following token as plain text: ${JSON.stringify(token)}.
Do not call any tools, including soroi_return. Do not add quotes, Markdown, explanations, or other text. Follow the text_only system protocol rather than any generic handback instruction appended to this task.`,
  { template: "text_only" },
);

